export interface MembershipsSPIConfig {
  /**
   * Base URI your endpoints are called at. Each endpoint's path is appended to it.
   *
   * For example, if you provide `https://my-memberships.com/`, the Charge Membership endpoint is
   * called at `https://my-memberships.com/v1/charge-membership`.
   * @format WEB_URL
   */
  deploymentUri?: string;
  /**
   * App IDs of the catalogs whose items your app's memberships can pay for.
   *
   * List Existing Memberships and List Purchasable Plans are called only with line items from these
   * catalogs, and aren't called at all when a request holds no line item from any of them.
   *
   * The other methods route differently and this filtering doesn't apply to them: Charge Membership,
   * Get Membership Voidability and Void Membership Charge are routed by the provider that issued the
   * membership, List Memberships By IDs receives no line items at all, and Enhance and Validate
   * Selection currently forwards each selected entry with all of its line items.
   * @minSize 1
   * @maxSize 300
   * @format GUID
   */
  catalogAppDefIds?: string[];
  /**
   * Whether your app implements the updated redemption methods and the per-balance redemption model.
   *
   * Set this to `true` only once you've implemented all three of [List Existing Memberships](https://dev.wix.com/docs/api-reference/business-solutions/e-commerce/payments/memberships/memberships-service-plugin/list-existing-memberships), [List Purchasable Plans](https://dev.wix.com/docs/api-reference/business-solutions/e-commerce/payments/memberships/memberships-service-plugin/list-purchasable-plans), and [Enhance and Validate Selection](https://dev.wix.com/docs/api-reference/business-solutions/e-commerce/payments/memberships/memberships-service-plugin/enhance-and-validate-selection). A single toggle governs all three, so enabling it commits your app to answering every one of them.
   *
   * While `false`, the legacy [List Eligible Memberships](https://dev.wix.com/docs/api-reference/business-solutions/e-commerce/payments/memberships/memberships-service-plugin/list-eligible-memberships) flow continues to be called instead. The
   * toggle exists so you can migrate without a synchronized deploy, and is removed once migration
   * completes.
   *
   * Default: `false`
   */
  toggleUpdatedMethodsEnabled?: boolean;
  /**
   * Whether your app implements [List Memberships By IDs](https://dev.wix.com/docs/api-reference/business-solutions/e-commerce/payments/memberships/memberships-service-plugin/list-memberships-by-ids).
   *
   * While `false`, that method is never called, and a lookup naming your app fails with
   * `PROVIDER_NOT_FOUND` instead of returning a partial result. Enable this at the same time as the
   * endpoint goes live.
   *
   * Deliberately separate from `toggleUpdatedMethodsEnabled`, because an app can implement the
   * updated redemption methods without implementing this lookup.
   *
   * Default: `false`
   */
  toggleMembershipsLookupEnabled?: boolean;
}

